import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import * as Popover from "@radix-ui/react-popover";
import { IconLoader2, IconPlus, IconSearch } from "@tabler/icons-react";
import { cn } from "@/lib/utils";

const wensityCardSurfaceSkinClass = cn(
  "border border-black/[0.08] bg-[radial-gradient(ellipse_90%_70%_at_50%_-10%,#ffffff_0%,#f4f4f5_72%)] [box-shadow:0_1px_2px_rgba(0,0,0,.06),0_8px_24px_-12px_rgba(0,0,0,.08)]",
  "dark:border-white/[0.06] dark:bg-[radial-gradient(ellipse_90%_70%_at_50%_-10%,#15151b_0%,#0a0a0b_72%)] dark:[box-shadow:0_1px_2px_rgba(0,0,0,.4),0_8px_24px_-12px_rgba(0,0,0,.6)]",
);

export type ComboboxSize = "sm" | "md" | "lg";
export type ComboboxStatus = "default" | "error" | "success";

export type ComboboxOption = {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  leading?: React.ReactNode;
  disabled?: boolean;
};

export type ComboboxGroup = {
  label?: React.ReactNode;
  options: ComboboxOption[];
};

export interface ComboboxProps
  extends Omit<
    React.ComponentPropsWithoutRef<typeof Popover.Root>,
    "children" | "modal" | "open" | "onOpenChange"
  > {
  id?: string;
  options: ComboboxOption[] | ComboboxGroup[];
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  multiple?: boolean;
  creatable?: boolean;
  onCreateOption?: (inputValue: string) => ComboboxOption | void;
  createLabel?: (inputValue: string) => React.ReactNode;
  loading?: boolean;
  onSearchChange?: (query: string) => void;
  /** Client-side filter. Set false when options are driven by `onSearchChange`. */
  filter?: boolean;
  name?: string;
  required?: boolean;
  disabled?: boolean;
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  success?: React.ReactNode;
  status?: ComboboxStatus;
  placeholder?: string;
  emptyMessage?: React.ReactNode;
  /** Screen reader copy when nothing is selected in `multiple` mode. */
  emptySelectionLabel?: React.ReactNode;
  /** Close the list when every selectable option is chosen in `multiple` mode. */
  closeWhenAllSelected?: boolean;
  comboboxSize?: ComboboxSize;
  fullWidth?: boolean;
  leadingIcon?: React.ReactNode;
  containerClassName?: string;
  triggerClassName?: string;
  contentClassName?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean | "true" | "false";
  "aria-required"?: boolean | "true" | "false";
}

const fieldSizes: Record<ComboboxSize, string> = {
  sm: "min-h-8 rounded-md",
  md: "min-h-10 rounded-lg",
  lg: "min-h-11 rounded-lg",
};

const inputSizes: Record<ComboboxSize, string> = {
  sm: "h-8 px-3 text-xs",
  md: "h-10 px-3.5 text-sm",
  lg: "h-11 px-4 text-[15px]",
};

const contentWidths: Record<ComboboxSize, string> = {
  sm: "min-w-[12rem]",
  md: "min-w-[15rem]",
  lg: "min-w-[17rem]",
};

const COMBOBOX_STYLE_ID = "wensity-combobox-styles";
const COMBOBOX_CHECK_PATH = "M3.25 8.1 6.35 11.2 12.75 4.6";
const COMBOBOX_ERROR_PATH_A = "M4.5 4.5 11.5 11.5";
const COMBOBOX_ERROR_PATH_B = "M11.5 4.5 4.5 11.5";

const EASE_OUT_CSS = "cubic-bezier(0.16, 1, 0.3, 1)";
const EASE_MORPH_CSS = "cubic-bezier(0.32, 0.72, 0, 1)";
const EASE_DRAWER_CSS = "cubic-bezier(0.32, 0.72, 0, 1)";

const COMBOBOX_STYLES = `
[data-wensity-combobox-root],
[data-wensity-combobox] {
  --wensity-combobox-success: var(--color-emerald-600, #059669);
  --wensity-combobox-error: var(--color-red-600, #dc2626);
  --wensity-combobox-ease-morph: ${EASE_MORPH_CSS};
  --wensity-combobox-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
}

.dark [data-wensity-combobox-root],
.dark [data-wensity-combobox] {
  --wensity-combobox-success: var(--color-emerald-400, #34d399);
  --wensity-combobox-error: var(--color-red-400, #f87171);
}

[data-wensity-combobox-shell] {
  transition:
    border-color 240ms var(--wensity-combobox-ease-morph),
    background-color 240ms var(--wensity-combobox-ease-morph),
    box-shadow 240ms var(--wensity-combobox-ease-morph);
}

[data-wensity-combobox][data-has-selection]:not([data-all-selected]) [data-wensity-combobox-shell]:not([data-open]) {
  background: color-mix(in srgb, var(--foreground) 2.5%, var(--background));
}

[data-wensity-combobox][data-all-selected] [data-wensity-combobox-shell] {
  border-color: color-mix(in srgb, var(--wensity-combobox-success) 48%, transparent);
  background: color-mix(in srgb, var(--wensity-combobox-success) 5%, var(--background));
}

[data-wensity-combobox][data-all-selected] [data-wensity-combobox-shell][data-open] {
  border-color: color-mix(in srgb, var(--wensity-combobox-success) 62%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--wensity-combobox-success) 14%, transparent);
}

[data-wensity-combobox-summary] {
  transition:
    opacity 180ms var(--wensity-combobox-ease-out),
    transform 180ms var(--wensity-combobox-ease-out);
}

[data-wensity-combobox][data-open] [data-wensity-combobox-summary] {
  opacity: 0;
  transform: translate3d(0, 2px, 0);
  pointer-events: none;
}

[data-slot="combobox-multi-check"] {
  display: grid;
  place-items: center;
  width: 1rem;
  height: 1rem;
  border-radius: 0.25rem;
  border: 1.5px solid color-mix(in srgb, var(--foreground) 18%, transparent);
  background: transparent;
  transition:
    border-color 180ms var(--wensity-combobox-ease-out),
    background-color 180ms var(--wensity-combobox-ease-out),
    transform 180ms var(--wensity-combobox-ease-out);
}

[data-selected="true"] [data-slot="combobox-multi-check"] {
  border-color: var(--foreground);
  background: var(--foreground);
  color: var(--background);
  transform: scale(1);
}

[data-selected="true"] [data-slot="combobox-multi-check"] svg {
  opacity: 1;
  transform: scale(1);
}

[data-slot="combobox-multi-check"] svg {
  opacity: 0;
  transform: scale(0.88);
  transition:
    opacity 140ms var(--wensity-combobox-ease-out),
    transform 140ms var(--wensity-combobox-ease-out);
}

[data-wensity-combobox][data-status="error"] [data-wensity-combobox-shell] {
  border-color: color-mix(in srgb, var(--wensity-combobox-error) 50%, transparent);
}

[data-wensity-combobox][data-status="error"] [data-wensity-combobox-shell][data-open] {
  border-color: color-mix(in srgb, var(--wensity-combobox-error) 72%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--wensity-combobox-error) 16%, transparent);
}

[data-wensity-combobox][data-status="success"] [data-wensity-combobox-shell] {
  border-color: color-mix(in srgb, var(--wensity-combobox-success) 50%, transparent);
}

[data-wensity-combobox][data-status="success"] [data-wensity-combobox-shell][data-open] {
  border-color: color-mix(in srgb, var(--wensity-combobox-success) 72%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--wensity-combobox-success) 16%, transparent);
}

[data-wensity-combobox-status-icon] {
  position: relative;
  display: inline-flex;
  width: 0;
  min-width: 0;
  overflow: hidden;
  align-items: center;
  justify-content: center;
  transition:
    width 240ms var(--wensity-combobox-ease-morph),
    min-width 240ms var(--wensity-combobox-ease-morph),
    margin-left 240ms var(--wensity-combobox-ease-morph);
}

[data-wensity-combobox][data-status="success"] [data-wensity-combobox-status-icon],
[data-wensity-combobox][data-status="error"] [data-wensity-combobox-status-icon] {
  width: 1rem;
  min-width: 1rem;
  margin-left: 0.125rem;
}

[data-slot="combobox-check"],
[data-slot="combobox-error-a"],
[data-slot="combobox-error-b"] {
  fill: none;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  opacity: 0;
  transition:
    stroke-dashoffset 120ms var(--wensity-combobox-ease-out) 0ms,
    opacity 100ms var(--wensity-combobox-ease-out) 0ms;
}

[data-wensity-combobox][data-status="success"] [data-slot="combobox-check"] {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset 220ms var(--wensity-combobox-ease-out) 80ms,
    opacity 160ms var(--wensity-combobox-ease-out) 80ms;
}

[data-wensity-combobox][data-status="error"] [data-slot="combobox-error-a"] {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset 200ms var(--wensity-combobox-ease-out) 0ms,
    opacity 140ms var(--wensity-combobox-ease-out) 0ms;
}

[data-wensity-combobox][data-status="error"] [data-slot="combobox-error-b"] {
  stroke-dashoffset: 0;
  opacity: 1;
  transition:
    stroke-dashoffset 200ms var(--wensity-combobox-ease-out) 60ms,
    opacity 140ms var(--wensity-combobox-ease-out) 60ms;
}

@keyframes wensity-combobox-message-enter {
  from {
    opacity: 0;
    transform: translate3d(0, 3px, 0);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }
}

[data-combobox-message] {
  animation: wensity-combobox-message-enter 240ms var(--wensity-combobox-ease-morph) both;
}

[data-wensity-combobox-content] {
  transform-origin: var(--radix-popover-content-transform-origin);
  backface-visibility: hidden;
}

[data-wensity-combobox-content][data-state="open"] {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition:
    opacity 220ms ${EASE_OUT_CSS},
    transform 260ms ${EASE_DRAWER_CSS};
}

[data-wensity-combobox-content][data-side="bottom"][data-state="open"] {
  @starting-style {
    opacity: 0;
    transform: translate3d(0, -8px, 0);
  }
}

[data-wensity-combobox-content][data-side="top"][data-state="open"] {
  @starting-style {
    opacity: 0;
    transform: translate3d(0, 8px, 0);
  }
}

[data-wensity-combobox-content][data-state="closed"] {
  opacity: 0;
  transition:
    opacity 180ms ${EASE_OUT_CSS},
    transform 220ms ${EASE_DRAWER_CSS};
}

[data-wensity-combobox-content][data-side="bottom"][data-state="closed"] {
  transform: translate3d(0, -6px, 0);
}

[data-wensity-combobox-content][data-side="top"][data-state="closed"] {
  transform: translate3d(0, 6px, 0);
}

[data-slot="combobox-item-check"] {
  display: inline-flex;
  transform: scale(0.92);
  opacity: 0;
  transition:
    transform 180ms ${EASE_OUT_CSS},
    opacity 180ms ${EASE_OUT_CSS};
}

[data-selected="true"] [data-slot="combobox-item-check"] {
  transform: scale(1);
  opacity: 1;

  @starting-style {
    transform: scale(0.92);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-wensity-combobox-shell],
  [data-wensity-combobox-status-icon],
  [data-slot="combobox-check"],
  [data-slot="combobox-error-a"],
  [data-slot="combobox-error-b"],
  [data-slot="combobox-item-check"],
  [data-wensity-combobox-content][data-state="open"],
  [data-wensity-combobox-content][data-state="closed"] {
    transition-duration: 0ms !important;
    transition-delay: 0ms !important;
    animation: none !important;
    transform: none !important;
  }

  [data-combobox-message] {
    animation: none !important;
    filter: none !important;
  }

  [data-slot="combobox-check"],
  [data-slot="combobox-error-a"],
  [data-slot="combobox-error-b"],
  [data-slot="combobox-item-check"] {
    stroke-dashoffset: 0;
    opacity: 1;
    transform: none;
  }
}
`;

function ensureComboboxStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(COMBOBOX_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = COMBOBOX_STYLE_ID;
  style.textContent = COMBOBOX_STYLES;
  document.head.appendChild(style);
}

function isGroupedOptions(
  options: ComboboxOption[] | ComboboxGroup[],
): options is ComboboxGroup[] {
  return options.length > 0 && "options" in options[0];
}

function flattenOptions(options: ComboboxOption[] | ComboboxGroup[]) {
  return isGroupedOptions(options)
    ? options.flatMap((group) => group.options)
    : options;
}

function getOptionLabelText(option: ComboboxOption) {
  return typeof option.label === "string" || typeof option.label === "number"
    ? String(option.label)
    : option.value;
}

function getListItemOptionId(
  listboxId: string,
  item: { type: "option"; option: ComboboxOption } | { type: "create"; value: string },
) {
  if (item.type === "create") return `${listboxId}-option-create`;
  return `${listboxId}-option-${item.option.value.replace(/[^a-zA-Z0-9_-]/g, "-")}`;
}

function buildSelectionSummary(
  selectedOptions: ComboboxOption[],
  selectedValues: string[],
  emptyLabel: string,
) {
  if (selectedValues.length === 0) return emptyLabel;
  const labels = selectedOptions.length
    ? selectedOptions.map((option) => getOptionLabelText(option))
    : selectedValues;
  return `${selectedValues.length} selected: ${labels.join(", ")}`;
}

function buildMultipleFieldSummary(
  selectedOptions: ComboboxOption[],
  selectedCount: number,
  totalSelectable: number,
) {
  if (selectedCount === 0) return null;
  if (totalSelectable > 0 && selectedCount >= totalSelectable) {
    return totalSelectable === 1
      ? getOptionLabelText(selectedOptions[0]!)
      : `All ${totalSelectable} selected`;
  }
  if (selectedCount === 1 && selectedOptions[0]) {
    return getOptionLabelText(selectedOptions[0]);
  }
  const first = selectedOptions[0] ? getOptionLabelText(selectedOptions[0]) : "";
  const remaining = selectedCount - 1;
  return remaining > 0 ? `${first} + ${remaining} more` : first;
}

function countSelectableOptions(options: ComboboxOption[]) {
  return options.filter((option) => !option.disabled).length;
}

function normalizeValue(
  value: string | string[] | undefined,
  multiple: boolean,
): string | string[] {
  if (multiple) {
    if (Array.isArray(value)) return value;
    if (value) return [value];
    return [];
  }
  return Array.isArray(value) ? (value[0] ?? "") : (value ?? "");
}

function ComboboxSuccessCheck() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className="size-4 text-[var(--wensity-combobox-success)]"
    >
      <path
        data-slot="combobox-check"
        d={COMBOBOX_CHECK_PATH}
        pathLength={1}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function ComboboxErrorX() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className="size-4 text-[var(--wensity-combobox-error)]"
    >
      <path
        data-slot="combobox-error-a"
        d={COMBOBOX_ERROR_PATH_A}
        pathLength={1}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
      <path
        data-slot="combobox-error-b"
        d={COMBOBOX_ERROR_PATH_B}
        pathLength={1}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

function ItemCheckIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 16 16" fill="none" className="size-2.5">
      <path
        d="M3.4 8.2 6.45 11.25 12.6 4.75"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function Combobox({
  options,
  id,
  value,
  defaultValue,
  onValueChange,
  open: controlledOpen,
  onOpenChange,
  multiple = false,
  creatable = false,
  onCreateOption,
  createLabel,
  loading = false,
  onSearchChange,
  filter = true,
  name,
  required,
  disabled,
  label,
  hint,
  error,
  success,
  status: statusProp,
  placeholder = "Search…",
  emptyMessage = "No results found.",
  emptySelectionLabel = "Nothing selected.",
  closeWhenAllSelected = true,
  comboboxSize = "md",
  fullWidth = true,
  leadingIcon,
  containerClassName,
  triggerClassName,
  contentClassName,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  "aria-required": ariaRequired,
  ...props
}: ComboboxProps) {
  const reactId = React.useId();
  const comboboxId = id ?? `wensity-combobox-${reactId}`;
  const labelId = label ? `${comboboxId}-label` : undefined;
  const listboxId = `${comboboxId}-listbox`;
  const hintId = hint ? `${comboboxId}-hint` : undefined;
  const errorId = error ? `${comboboxId}-error` : undefined;
  const successId = success ? `${comboboxId}-success` : undefined;
  const selectionSummaryId = multiple ? `${comboboxId}-selection-summary` : undefined;

  const inputRef = React.useRef<HTMLInputElement>(null);
  const shellRef = React.useRef<HTMLDivElement>(null);
  const [openState, setOpenState] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const [highlightIndex, setHighlightIndex] = React.useState(0);
  const [createdOptions, setCreatedOptions] = React.useState<ComboboxOption[]>([]);
  const [uncontrolledValue, setUncontrolledValue] = React.useState(() =>
    normalizeValue(defaultValue, multiple),
  );

  const open = controlledOpen ?? openState;
  const selectedValue = value ?? uncontrolledValue;
  const authoredOptions = React.useMemo(() => flattenOptions(options), [options]);
  const localCreatedOptions = React.useMemo(() => {
    if (createdOptions.length === 0) return [];

    const authoredValues = new Set(authoredOptions.map((option) => option.value));
    return createdOptions.filter((option) => !authoredValues.has(option.value));
  }, [authoredOptions, createdOptions]);
  const flattenedOptions = React.useMemo(
    () =>
      localCreatedOptions.length > 0
        ? [...authoredOptions, ...localCreatedOptions]
        : authoredOptions,
    [authoredOptions, localCreatedOptions],
  );

  const resolvedStatus: ComboboxStatus =
    statusProp ?? (error ? "error" : success ? "success" : "default");

  const selectedValues = multiple
    ? (Array.isArray(selectedValue) ? selectedValue : [])
    : selectedValue
      ? [selectedValue as string]
      : [];

  const selectedOptions = flattenedOptions.filter((option) =>
    selectedValues.includes(option.value),
  );
  const selectableCount = countSelectableOptions(flattenedOptions);
  const hasSelection = selectedValues.length > 0;
  const allSelected =
    multiple && hasSelection && selectableCount > 0 && selectedValues.length >= selectableCount;

  const describedBy =
    [ariaDescribedBy, errorId, successId, hintId, selectionSummaryId]
      .filter(Boolean)
      .join(" ") || undefined;

  const selectionSummaryText = multiple
    ? buildSelectionSummary(
        selectedOptions,
        selectedValues,
        typeof emptySelectionLabel === "string"
          ? emptySelectionLabel
          : "Nothing selected.",
      )
    : "";

  const filterQuery = filter ? query.trim().toLowerCase() : "";

  const filteredFlat = React.useMemo(() => {
    if (!filterQuery) return flattenedOptions;
    return flattenedOptions.filter((option) => {
      const labelText = getOptionLabelText(option).toLowerCase();
      const descriptionText =
        typeof option.description === "string"
          ? option.description.toLowerCase()
          : "";
      return (
        labelText.includes(filterQuery) ||
        option.value.toLowerCase().includes(filterQuery) ||
        descriptionText.includes(filterQuery)
      );
    });
  }, [filterQuery, flattenedOptions]);

  const canCreate =
    creatable &&
    query.trim().length > 0 &&
    !flattenedOptions.some(
      (option) =>
        getOptionLabelText(option).toLowerCase() === query.trim().toLowerCase() ||
        option.value.toLowerCase() === query.trim().toLowerCase(),
    );

  const listItems = React.useMemo(() => {
    const items: Array<
      | { type: "option"; option: ComboboxOption; groupLabel?: React.ReactNode }
      | { type: "create"; value: string }
    > = [];

    if (isGroupedOptions(options) && !filterQuery) {
      for (const group of options) {
        for (const option of group.options) {
          items.push({ type: "option", option, groupLabel: group.label });
        }
      }
      for (const option of localCreatedOptions) {
        items.push({ type: "option", option });
      }
    } else if (isGroupedOptions(options) && filterQuery) {
      for (const group of options) {
        const groupMatches = group.options.filter((option) =>
          filteredFlat.some((match) => match.value === option.value),
        );
        for (const option of groupMatches) {
          items.push({ type: "option", option, groupLabel: group.label });
        }
      }
      const matchedValues = new Set(filteredFlat.map((option) => option.value));
      for (const option of localCreatedOptions) {
        if (matchedValues.has(option.value)) {
          items.push({ type: "option", option });
        }
      }
    } else {
      for (const option of filteredFlat) {
        items.push({ type: "option", option });
      }
    }

    if (canCreate) {
      items.push({ type: "create", value: query.trim() });
    }

    return items;
  }, [canCreate, filterQuery, filteredFlat, localCreatedOptions, options, query]);

  const displayInputValue = open
    ? query
    : multiple
      ? ""
      : selectedOptions[0]
        ? getOptionLabelText(selectedOptions[0])
        : typeof selectedValue === "string"
          ? selectedValue
          : "";

  const multipleFieldSummary =
    multiple && !open
      ? buildMultipleFieldSummary(
          selectedOptions,
          selectedValues.length,
          selectableCount,
        )
      : null;

  const inputPlaceholder =
    open && multiple && hasSelection
      ? "Search to add or remove…"
      : placeholder;

  const clearQuery = React.useCallback(() => {
    setQuery("");
    onSearchChange?.("");
  }, [onSearchChange]);

  const handleOpenChange = React.useCallback(
    (nextOpen: boolean) => {
      if (controlledOpen === undefined) setOpenState(nextOpen);
      onOpenChange?.(nextOpen);
      if (!nextOpen) {
        clearQuery();
        setHighlightIndex(0);
      }
    },
    [clearQuery, controlledOpen, onOpenChange],
  );

  const commitValue = React.useCallback(
    (next: string | string[]) => {
      if (value === undefined) setUncontrolledValue(next);
      onValueChange?.(next);
    },
    [onValueChange, value],
  );

  const selectOption = React.useCallback(
    (option: ComboboxOption) => {
      if (option.disabled) return;

      if (multiple) {
        const current = Array.isArray(selectedValue) ? selectedValue : [];
        const exists = current.includes(option.value);
        const next = exists
          ? current.filter((item) => item !== option.value)
          : [...current, option.value];
        commitValue(next);

        const willBeAllSelected =
          !exists &&
          selectableCount > 0 &&
          next.length >= selectableCount &&
          closeWhenAllSelected;

        if (willBeAllSelected) {
          handleOpenChange(false);
        } else {
          clearQuery();
          inputRef.current?.focus();
        }
      } else {
        commitValue(option.value);
        handleOpenChange(false);
      }
    },
    [
      closeWhenAllSelected,
      clearQuery,
      commitValue,
      handleOpenChange,
      multiple,
      selectableCount,
      selectedValue,
    ],
  );

  const handleCreate = React.useCallback(() => {
    const trimmed = query.trim();
    if (!trimmed || !creatable) return;

    const created = onCreateOption?.(trimmed) ?? {
      value: trimmed.toLowerCase().replace(/\s+/g, "-"),
      label: trimmed,
    };

    if (!created) return;
    setCreatedOptions((current) =>
      current.some((option) => option.value === created.value)
        ? current
        : [...current, created],
    );
    selectOption(created);
  }, [creatable, onCreateOption, query, selectOption]);

  const handleInputChange = React.useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const nextQuery = event.target.value;
      setQuery(nextQuery);
      setHighlightIndex(0);
      onSearchChange?.(nextQuery);
      if (!open) handleOpenChange(true);
    },
    [handleOpenChange, onSearchChange, open],
  );

  const handleInputFocus = React.useCallback(() => {
    if (!disabled && !open) handleOpenChange(true);
  }, [disabled, handleOpenChange, open]);

  const handleShellPointerDown = React.useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (disabled) return;

      const target = event.target as HTMLElement;
      const input = inputRef.current;
      const isChevron = Boolean(target.closest("[data-wensity-combobox-chevron]"));
      const isInputTarget = Boolean(input && (target === input || input.contains(target)));

      if (isChevron) {
        event.preventDefault();
        if (open) {
          handleOpenChange(false);
          input?.blur();
        } else {
          input?.focus();
          handleOpenChange(true);
        }
        return;
      }

      if (open) {
        if (isInputTarget && input) {
          if (!query.trim() && document.activeElement === input) {
            event.preventDefault();
            handleOpenChange(false);
            input.blur();
          }
          return;
        }

        event.preventDefault();
        handleOpenChange(false);
        input?.blur();
        return;
      }

      if (input && !isInputTarget) {
        event.preventDefault();
        input.focus();
      }
      handleOpenChange(true);
    },
    [disabled, handleOpenChange, open, query],
  );

  const handleInputKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      if (event.key === "ArrowDown") {
        event.preventDefault();
        if (!open) handleOpenChange(true);
        setHighlightIndex((current) =>
          Math.min(current + 1, Math.max(listItems.length - 1, 0)),
        );
        return;
      }

      if (event.key === "ArrowUp") {
        event.preventDefault();
        setHighlightIndex((current) => Math.max(current - 1, 0));
        return;
      }

      if (event.key === "Enter") {
        event.preventDefault();
        const item = listItems[highlightIndex];
        if (!item) return;
        if (item.type === "create") {
          handleCreate();
        } else {
          selectOption(item.option);
        }
        return;
      }

      if (event.key === "Escape") {
        event.preventDefault();
        handleOpenChange(false);
        return;
      }

      if (event.key === "Backspace" && multiple && !query && selectedValues.length) {
        const next = selectedValues.slice(0, -1);
        commitValue(next);
      }
    },
    [
      commitValue,
      handleCreate,
      handleOpenChange,
      highlightIndex,
      listItems,
      multiple,
      open,
      query,
      selectOption,
      selectedValues,
    ],
  );

  React.useLayoutEffect(() => {
    ensureComboboxStyles();
  }, []);

  React.useEffect(() => {
    const input = inputRef.current;
    if (!input) return;

    const isMissingRequiredSelection = Boolean(required && !disabled && !hasSelection);
    input.setCustomValidity(
      isMissingRequiredSelection ? "Please select an option." : "",
    );

    return () => input.setCustomValidity("");
  }, [disabled, hasSelection, required]);

  React.useEffect(() => {
    if (highlightIndex >= listItems.length) {
      setHighlightIndex(Math.max(listItems.length - 1, 0));
    }
  }, [highlightIndex, listItems.length]);

  const activeDescendantId =
    open && listItems[highlightIndex]
      ? getListItemOptionId(listboxId, listItems[highlightIndex])
      : undefined;

  React.useEffect(() => {
    if (!open || !activeDescendantId) return;
    document.getElementById(activeDescendantId)?.scrollIntoView({ block: "nearest" });
  }, [activeDescendantId, highlightIndex, open]);

  const renderListItem = (
    item: (typeof listItems)[number],
    index: number,
    showGroupLabel?: React.ReactNode,
  ) => {
    if (item.type === "create") {
      return (
        <button
          key="__create__"
          id={getListItemOptionId(listboxId, item)}
          type="button"
          role="option"
          aria-selected={false}
          aria-disabled={false}
          data-highlighted={highlightIndex === index ? "" : undefined}
          onMouseEnter={() => setHighlightIndex(index)}
          onClick={handleCreate}
          className={cn(
            "flex w-full min-h-10 cursor-default items-center gap-2.5 rounded-lg px-3 py-2.5 text-left text-sm outline-none",
            "text-[var(--foreground)]",
            highlightIndex === index &&
              "bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))] dark:bg-[color-mix(in_srgb,var(--foreground)_10%,var(--background))]",
          )}
        >
          <span className="grid size-7 shrink-0 place-items-center rounded-md border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))] text-[var(--muted-foreground)]">
            <IconPlus stroke={1.75} className="size-4" />
          </span>
          <span className="min-w-0 flex-1 truncate font-medium tracking-[-0.01em]">
            {createLabel ? createLabel(item.value) : `Create "${item.value}"`}
          </span>
        </button>
      );
    }

    const { option } = item;
    const isSelected = selectedValues.includes(option.value);

    return (
      <React.Fragment key={option.value}>
        {showGroupLabel ? (
          <div className="px-3 pb-1 pt-2 text-[11px] font-semibold uppercase tracking-[0.07em] text-[var(--muted-foreground)]">
            {showGroupLabel}
          </div>
        ) : null}
        <button
          id={getListItemOptionId(listboxId, item)}
          type="button"
          role="option"
          aria-selected={isSelected}
          aria-disabled={option.disabled || undefined}
          data-selected={isSelected ? "true" : undefined}
          disabled={option.disabled}
          data-highlighted={highlightIndex === index ? "" : undefined}
          onMouseEnter={() => setHighlightIndex(index)}
          onClick={() => selectOption(option)}
          className={cn(
            "relative flex w-full min-h-10 cursor-default select-none items-start gap-3 rounded-lg px-3 py-2.5 text-left outline-none",
            "text-sm text-[var(--foreground)]",
            "disabled:pointer-events-none disabled:opacity-40",
            highlightIndex === index &&
              "bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))] dark:bg-[color-mix(in_srgb,var(--foreground)_10%,var(--background))]",
            isSelected &&
              "bg-[color-mix(in_srgb,var(--foreground)_7%,var(--background))] dark:bg-[color-mix(in_srgb,var(--foreground)_13%,var(--background))]",
          )}
        >
          {option.leading ? (
            <span className="mt-0.5 grid size-7 shrink-0 place-items-center rounded-md border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))] text-[var(--muted-foreground)] [&_svg]:size-4">
              {option.leading}
            </span>
          ) : null}
          <span className="min-w-0 flex-1">
            <span className="block truncate font-medium tracking-[-0.01em]">
              {option.label}
            </span>
            {option.description ? (
              <span className="mt-1 block text-[12px] leading-[1.4] text-[var(--muted-foreground)]">
                {option.description}
              </span>
            ) : null}
          </span>
          {multiple ? (
            <span
              data-slot="combobox-multi-check"
              aria-hidden="true"
              className="absolute right-3 top-1/2 -translate-y-1/2 shrink-0"
            >
              <ItemCheckIcon />
            </span>
          ) : null}
        </button>
      </React.Fragment>
    );
  };

  const renderedGroups = new Set<string>();

  return (
    <div
      data-wensity-combobox-root=""
      className={cn(
        "flex flex-col gap-1.5",
        fullWidth ? "w-full" : "w-fit",
        containerClassName,
      )}
    >
      {label ? (
        <label
          id={labelId}
          htmlFor={comboboxId}
          className="text-[13px] font-normal leading-none tracking-[-0.01em] text-[var(--foreground)]"
        >
          {label}
        </label>
      ) : null}

      {multiple ? (
        <span id={selectionSummaryId} className="sr-only" aria-live="polite" aria-atomic="true">
          {selectionSummaryText}
        </span>
      ) : null}

      <Popover.Root open={open} onOpenChange={handleOpenChange} modal={false} {...props}>
        <Popover.Anchor asChild>
          <div
            data-wensity-combobox=""
            data-status={resolvedStatus}
            data-has-selection={hasSelection ? "" : undefined}
            data-all-selected={allSelected ? "" : undefined}
            className={cn(fullWidth ? "w-full" : "w-fit")}
          >
            <div
              ref={shellRef}
              data-wensity-combobox-shell=""
              data-open={open ? "" : undefined}
              onPointerDown={handleShellPointerDown}
              className={cn(
                "group/combobox relative flex cursor-text items-center gap-2 border border-[var(--border)] bg-[var(--background)]",
                "shadow-[0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.28)]",
                "focus-within:border-[color-mix(in_srgb,var(--foreground)_24%,transparent)]",
                "hover:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)]",
                fieldSizes[comboboxSize],
                disabled && "cursor-not-allowed opacity-45",
                triggerClassName,
              )}
            >
              <span className="inline-flex shrink-0 pl-3 text-[var(--muted-foreground)] [&_svg]:size-4">
                {leadingIcon ?? <IconSearch stroke={1.75} aria-hidden="true" />}
              </span>

              <div
                data-wensity-combobox-field=""
                className="relative flex min-h-0 min-w-0 flex-1 items-center self-stretch py-0.5"
              >
                {multipleFieldSummary ? (
                  <span
                    data-wensity-combobox-summary=""
                    aria-hidden="true"
                    className={cn(
                      "pointer-events-none absolute inset-y-0 left-0 flex max-w-[calc(100%-0.25rem)] items-center truncate text-sm font-medium tracking-[-0.015em] text-[var(--foreground)]",
                      allSelected && "text-[var(--wensity-combobox-success)]",
                    )}
                  >
                    {multipleFieldSummary}
                  </span>
                ) : null}

                <input
                  ref={inputRef}
                  id={comboboxId}
                  type="text"
                  role="combobox"
                  autoComplete="off"
                  autoCorrect="off"
                  spellCheck={false}
                  aria-expanded={open}
                  aria-haspopup="listbox"
                  aria-controls={listboxId}
                  aria-autocomplete="list"
                  aria-activedescendant={activeDescendantId}
                  aria-labelledby={labelId}
                  aria-invalid={ariaInvalid ?? (error ? true : undefined)}
                  aria-describedby={describedBy}
                  aria-required={ariaRequired ?? required ?? undefined}
                  aria-busy={loading || undefined}
                  required={required && !hasSelection}
                  disabled={disabled}
                  placeholder={multipleFieldSummary ? undefined : inputPlaceholder}
                  value={displayInputValue}
                  onChange={handleInputChange}
                  onFocus={handleInputFocus}
                  onKeyDown={handleInputKeyDown}
                  className={cn(
                    "w-full min-w-0 border-0 bg-transparent text-[var(--foreground)] outline-none",
                    "placeholder:text-[var(--muted-foreground)]/60",
                    "disabled:cursor-not-allowed",
                    inputSizes[comboboxSize],
                    "h-auto min-h-0 px-0 py-0",
                    multipleFieldSummary &&
                      !open &&
                      "text-transparent caret-[var(--foreground)]",
                  )}
                />
              </div>

              {multiple && hasSelection ? (
                <span
                  aria-hidden="true"
                  className={cn(
                    "shrink-0 tabular-nums text-[11px] font-medium tracking-[-0.01em]",
                    allSelected
                      ? "text-[var(--wensity-combobox-success)]"
                      : "text-[var(--muted-foreground)]",
                  )}
                >
                  {selectedValues.length}/{selectableCount}
                </span>
              ) : null}

              <span
                data-wensity-combobox-status-icon=""
                aria-hidden="true"
                className="shrink-0 pr-1"
              >
                {resolvedStatus === "success" && !allSelected ? (
                  <ComboboxSuccessCheck />
                ) : null}
                {resolvedStatus === "error" ? <ComboboxErrorX /> : null}
              </span>

              {loading ? (
                <span
                  aria-hidden="true"
                  className="mr-3 inline-flex shrink-0 text-[var(--muted-foreground)]"
                >
                  <IconLoader2 stroke={1.75} className="size-4 animate-spin" />
                </span>
              ) : (
                <span
                  data-wensity-combobox-chevron=""
                  aria-hidden="true"
                  className={cn(
                    "mr-3 inline-flex shrink-0 cursor-pointer text-[var(--muted-foreground)] transition-transform duration-[220ms] ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-none",
                    open && "rotate-180",
                  )}
                >
                  <svg viewBox="0 0 16 16" fill="none" className="size-4">
                    <path
                      d="m4.25 6.25 3.75 3.5 3.75-3.5"
                      stroke="currentColor"
                      strokeWidth="1.7"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </span>
              )}
            </div>
          </div>
        </Popover.Anchor>

        <Popover.Portal>
          <Popover.Content
            align="start"
            sideOffset={8}
            collisionPadding={12}
            data-wensity-combobox-content=""
            onOpenAutoFocus={(event) => event.preventDefault()}
            onInteractOutside={(event) => {
              if (
                inputRef.current?.contains(event.target as Node) ||
                shellRef.current?.contains(event.target as Node)
              ) {
                event.preventDefault();
              }
            }}
            className={cn(
              wensityCardSurfaceSkinClass,
              "relative isolate z-50 max-h-[min(22rem,var(--radix-popover-content-available-height))] overflow-x-hidden overflow-y-auto rounded-xl p-1.5 text-[var(--foreground)]",
              contentWidths[comboboxSize],
              fullWidth && "w-[var(--radix-popover-trigger-width)]",
              contentClassName,
            )}
          >
            <div
              id={listboxId}
              role="listbox"
              aria-multiselectable={multiple || undefined}
              className="space-y-0.5"
            >
              {multiple && listItems.length > 0 ? (
                <div className="mb-1 flex items-center justify-between gap-3 border-b border-[var(--border)] px-3 pb-2 pt-1">
                  <span className="text-[11px] font-medium tracking-[-0.01em] text-[var(--muted-foreground)]">
                    {selectedValues.length} of {selectableCount} selected
                  </span>
                  {allSelected ? (
                    <span className="text-[11px] font-medium text-[var(--wensity-combobox-success)]">
                      Complete
                    </span>
                  ) : null}
                </div>
              ) : null}
              {loading && listItems.length === 0 ? (
                <div
                  role="status"
                  className="flex min-h-16 items-center justify-center gap-2 px-3 text-[12px] text-[var(--muted-foreground)]"
                >
                  <IconLoader2 stroke={1.75} className="size-4 animate-spin" aria-hidden="true" />
                  Loading…
                </div>
              ) : listItems.length === 0 ? (
                <div role="status" className="px-3 py-6 text-center text-[12px] text-[var(--muted-foreground)]">
                  {emptyMessage}
                </div>
              ) : (
                listItems.map((item, index) => {
                  let showLabel: React.ReactNode | undefined;
                  if (item.type === "option" && item.groupLabel) {
                    const key =
                      typeof item.groupLabel === "string" ||
                      typeof item.groupLabel === "number"
                        ? String(item.groupLabel)
                        : `group-${index}`;
                    if (!renderedGroups.has(key)) {
                      renderedGroups.add(key);
                      showLabel = item.groupLabel;
                    }
                  }
                  return renderListItem(item, index, showLabel);
                })
              )}
            </div>
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>

      {name ? (
        multiple ? (
          selectedValues.map((item) => (
            <input key={item} type="hidden" name={`${name}[]`} value={item} />
          ))
        ) : (
          <input type="hidden" name={name} value={(selectedValue as string) ?? ""} />
        )
      ) : null}

      {error ? (
        <p
          id={errorId}
          data-combobox-message=""
          className="text-[12px] leading-[1.45] font-medium text-[var(--wensity-combobox-error)]"
        >
          {error}
        </p>
      ) : success ? (
        <p
          id={successId}
          data-combobox-message=""
          className="text-[12px] leading-[1.45] font-medium text-[var(--wensity-combobox-success)]"
        >
          {success}
        </p>
      ) : hint ? (
        <p
          id={hintId}
          className="text-[12px] leading-[1.45] text-[var(--muted-foreground)]"
        >
          {hint}
        </p>
      ) : null}
    </div>
  );
}
